class EightPuzzle:
    GOAL_STATE = [[1, 2, 3], [4, 5, 6], [7, 8, 0]]
    GRID_SIZE = 3
    BLANK_VALUE = 0

    DIRECTION_UP = 'up'
    DIRECTION_DOWN = 'down'
    DIRECTION_LEFT = 'left'
    DIRECTION_RIGHT = 'right'

    def __init__(self, initial_state):
        self.initial_state = initial_state

    def find_blank(self, state):
        for i in range(self.GRID_SIZE):
            for j in range(self.GRID_SIZE):
                if state[i][j] == self.BLANK_VALUE:
                    return i, j
        return None

    def _swap_blank_with_neighbor(self, state, i, j, direction):
        new_state = [row[:] for row in state]

        if direction == self.DIRECTION_UP:
            ni, nj = i - 1, j
        elif direction == self.DIRECTION_DOWN:
            ni, nj = i + 1, j
        elif direction == self.DIRECTION_LEFT:
            ni, nj = i, j - 1
        elif direction == self.DIRECTION_RIGHT:
            ni, nj = i, j + 1
        else:
            raise ValueError(f"Invalid direction: {direction}")

        new_state[i][j], new_state[ni][nj] = new_state[ni][nj], new_state[i][j]
        return new_state

    def move(self, state, direction):
        i, j = self.find_blank(state)
        return self._swap_blank_with_neighbor(state, i, j, direction)

    def get_possible_moves(self, state):
        moves = []
        i, j = self.find_blank(state)

        if self._can_move_up(i, j):
            moves.append(self.DIRECTION_UP)
        if self._can_move_down(i, j):
            moves.append(self.DIRECTION_DOWN)
        if self._can_move_left(i, j):
            moves.append(self.DIRECTION_LEFT)
        if self._can_move_right(i, j):
            moves.append(self.DIRECTION_RIGHT)

        return moves

    def _can_move_up(self, i, j):
        return i > 0

    def _can_move_down(self, i, j):
        return i < self.GRID_SIZE - 1

    def _can_move_left(self, i, j):
        return j > 0

    def _can_move_right(self, i, j):
        return j < self.GRID_SIZE - 1

    def _is_goal(self, state):
        return state == self.GOAL_STATE

    def _is_in_closed_list(self, state, closed_list):
        return state in closed_list

    def solve(self):
        open_list = [(self.initial_state, [])]
        closed_list = []

        while open_list:
            current_state, path = open_list.pop(0)
            closed_list.append(current_state)

            if self._is_goal(current_state):
                return path

            for move in self.get_possible_moves(current_state):
                new_state = self.move(current_state, move)
                if not self._is_in_closed_list(new_state, closed_list):
                    open_list.append((new_state, self._extend_path(path, move)))

        return None

    def _extend_path(self, path, move):
        return path + [move]
